'use strict';
let projectFilter='all',projectView='timeline';
const projectLabels={active:'В работе',risk:'Под угрозой',overdue:'Просрочен',done:'Завершён'};
const stageLabels={planned:'Запланирован',waiting:'Ожидает предыдущий этап',active:'В работе',blocked:'Заблокирован',done:'Завершён'};
function projectBadge(status){return `<span class="badge ${status==='done'?'paid':status==='risk'||status==='blocked'||status==='overdue'?'overdue':'partial'}">${esc(tr(projectLabels[status]||stageLabels[status]||status))}</span>`;}
function projectProgress(p){return `<div class="project-progress"><div class="progress" role="progressbar" aria-label="${esc(tr('Выполнение этапов'))}" aria-valuenow="${p.progress}" aria-valuemin="0" aria-valuemax="100"><div style="width:${p.progress}%"></div></div><strong>${n(p.progress)}%</strong></div>`;}
function projects(){
 const all=data.projects||[],counts={all:all.length,active:all.filter(p=>p.project_status!=='done').length,risk:all.filter(p=>['risk','overdue'].includes(p.project_status)).length,done:all.filter(p=>p.project_status==='done').length};
 const rows=all.filter(p=>projectFilter==='all'||projectFilter==='active'&&p.project_status!=='done'||projectFilter==='risk'&&['risk','overdue'].includes(p.project_status)||projectFilter==='done'&&p.project_status==='done');
 const filters={all:'Все проекты',active:'В работе',risk:'Требуют внимания',done:'Завершены'};
 return `<div class="project-intro"><p>Проектные этапы, отгрузки и оплаты учитываются отдельно.</p><span class="badge">Демонстрационные проекты</span></div><div class="metrics project-filters">${Object.entries(filters).map(([key,label])=>`<button class="metric ${projectFilter===key?'emphasis':''}" data-project-filter="${key}" aria-pressed="${projectFilter===key}"><span class="metric-label">${label}</span><strong class="metric-value">${counts[key]}</strong></button>`).join('')}</div><div class="project-cards">${rows.map(p=>{
 const next=p.stages.find(s=>s.stage_status!=='done'),blocked=p.stages.find(s=>s.stage_status==='blocked');
 return `<article class="panel project-card"><div class="panel-head"><span class="eyebrow">PR-${p.project_id}</span>${projectBadge(p.project_status)}</div><h2><a href="#projects/project/${p.project_id}" data-project="${p.project_id}">${esc(tr(p.title))}</a></h2><p class="muted">${esc(p.customer)} · <span>${esc(tr(p.owner))}</span></p>${projectProgress(p)}<p class="note"><bdi>${n(p.done_count)} / ${n(p.stage_count)}</bdi> <span>этапов принято</span></p><div class="project-dates"><span><small>Согласованный срок</small><strong>${d(p.deadline)}</strong></span><span><small>Прогноз завершения</small><strong class="${p.forecast_at>p.deadline?'shortage':''}">${d(p.forecast_at)}</strong></span></div><div class="project-next"><small>${next?'Ближайший этап':'Проект завершён'}</small><strong>${next?esc(tr(next.title)):d(p.completed_at)}</strong>${blocked?`<p class="shortage">${esc(tr(blocked.block_reason))}</p>`:''}</div><div class="project-card-actions"><button class="back-button" data-project="${p.project_id}">Открыть проект</button><button class="order-link" data-order="${p.order_id}"><span>Заказ</span> № ${p.order_id}</button></div></article>`;
 }).join('')||emptyState('Нет проектов за выбранный период.')} </div><p class="note">Прогресс — доля принятых этапов с учётом веса. Прогнозные даты не являются фактическими отгрузками.</p>`;
}
function projectStageInfo(s,p){
 const dependency=p.stages.find(x=>x.stage_no===s.depends_on);
 return `<details class="project-stage-info"><summary>${s.stage_no}. ${esc(tr(s.title))}</summary><p><b>Критерий приёмки</b><br>${esc(tr(s.acceptance))}</p>${dependency?`<p><b>Зависимость</b><br>${dependency.stage_no}. ${esc(tr(dependency.title))}</p>`:''}<p><b>Вес этапа</b>: ${s.weight}%</p>${s.actual_start?`<p><b>Фактическое начало</b>: ${d(s.actual_start)}</p>`:''}${s.completed_at?`<p><b>Принят</b>: ${d(s.completed_at)}</p>`:''}${s.block_reason?`<p class="shortage">${esc(tr(s.block_reason))}</p>`:''}</details>`;
}
function projectDetail(p){
 const order=[...data.orders,...(data.related_orders||[])].find(o=>o.order_id===p.order_id);
 const stages=p.stages,blocked=stages.find(s=>s.stage_status==='blocked');
 const from=new Date(p.started_at+'T12:00:00'),to=new Date(p.deadline+'T12:00:00'),span=Math.max(1,(to-from)/86400000+1);
 const schedule=s=>{const left=Math.max(0,(new Date(s.planned_start+'T12:00:00')-from)/86400000/span*100),width=Math.max(1,((new Date(s.planned_end+'T12:00:00')-new Date(s.planned_start+'T12:00:00'))/86400000+1)/span*100);return `<div class="stage-schedule" title="${d(s.planned_start)} — ${d(s.planned_end)}"><i class="${s.stage_status}" style="inset-inline-start:${left}%;width:${Math.min(width,100-left)}%"></i></div>`;};
 const timeline=`<div class="table-wrap"><table><thead><tr><th>Этап</th><th>Ответственный</th><th>Плановые даты</th><th>Статус</th><th class="project-timeline-heading"><span>План этапов</span><small>${d(p.started_at)} — ${d(p.deadline)}</small></th></tr></thead><tbody>${stages.map(s=>`<tr><td>${projectStageInfo(s,p)}</td><td>${esc(tr(s.owner))}</td><td>${d(s.planned_start)} — ${d(s.planned_end)}</td><td>${projectBadge(s.stage_status)}</td><td>${schedule(s)}</td></tr>`).join('')}</tbody></table></div>`;
 const groups=[['planned','План / ожидание'],['active','В работе'],['blocked','Заблокирован'],['done','Завершены']];
 const board=`<div class="project-board">${groups.map(([key,title])=>{const rows=stages.filter(s=>key==='planned'?['planned','waiting'].includes(s.stage_status):s.stage_status===key);return `<section class="project-lane"><h3>${title} <span>${rows.length}</span></h3>${rows.map(s=>`<article class="project-task">${projectStageInfo(s,p)}<p class="muted">${esc(tr(s.owner))} · ${d(s.planned_end)}</p>${projectBadge(s.stage_status)}</article>`).join('')||'<p class="muted">Нет этапов</p>'}</section>`;}).join('')}</div>`;
 const components=data.order_bom.filter(b=>b.order_id===p.order_id&&Number(b.open_needed)>0).reduce((acc,b)=>{acc.set(b.component_id,(acc.get(b.component_id)||0)+Number(b.open_needed));return acc;},new Map());
 return `<div class="project-detail"><section class="panel"><div class="panel-head"><div><p class="eyebrow">PR-${p.project_id} · <span>Проект</span></p><h2>${esc(tr(p.title))}</h2><p>${esc(p.customer)} · ${esc(tr(p.owner))}</p></div>${projectBadge(p.project_status)}</div><div class="project-overview"><div><h3>Выполнение этапов</h3>${projectProgress(p)}<p class="note"><bdi>${p.done_count} / ${p.stage_count}</bdi> <span>этапов принято</span></p></div><div><small>Согласованный срок</small><strong>${d(p.deadline)}</strong></div><div><small>Прогноз завершения</small><strong class="${p.forecast_at>p.deadline?'shortage':''}">${d(p.forecast_at)}</strong></div><div><small>Сумма заказа</small><strong>${n(p.order_amount)} ₪</strong></div></div>${blocked?`<div class="detail-reason"><strong>Требуется решение</strong><span>${esc(tr(blocked.block_reason))}</span><small>${esc(tr(blocked.owner))} · ${esc(tr(blocked.title))}</small></div>`:''}<div class="project-order-summary"><button class="order-link" data-order="${p.order_id}"><span>Открыть заказ</span> № ${p.order_id}</button>${order?`<span>${badge(order.fulfillment_status)}</span><span><span>Отгружено</span>: ${n(order.shipped_amount)} ₪</span><span><span>Оплачено</span>: ${n(order.paid_amount)} ₪</span>`:''}</div></section><section class="panel"><div class="panel-head"><div><h2>Этапы проекта</h2><p>Нажмите на этап, чтобы увидеть критерии приёмки и зависимости.</p></div><div class="project-view-switch"><button class="back-button" data-project-view="timeline" aria-pressed="${projectView==='timeline'}">План этапов</button><button class="back-button" data-project-view="board" aria-pressed="${projectView==='board'}">Канбан</button></div></div>${projectView==='board'?board:timeline}</section><section class="panel"><div class="panel-head"><div><h2>Комплектующие проекта</h2><p>Потребность по неотгруженным позициям связанного заказа.</p></div></div>${components.size?`<div class="table-wrap"><table><thead><tr><th>Компонент</th><th class="num">Потребность заказа</th><th class="num">Доступно на складе</th><th class="num">Общий дефицит</th></tr></thead><tbody>${[...components].map(([id,needed])=>{const c=data.supply.find(x=>x.component_id===id);return c?`<tr><td><button class="order-link" data-component="${id}">${esc(tr(c.name))}</button></td><td class="num">${n(needed)}</td><td class="num">${n(c.available)}</td><td class="num ${c.shortage?'shortage':''}">${n(c.shortage)}</td></tr>`:'';}).join('')}</tbody></table></div>`:'<p class="muted">Открытой потребности нет.</p>'}<p class="note">Остаток и общий дефицит относятся ко всей фабрике, без распределения между проектами.</p></section><p class="note">Учебный обзор проектов. Изменение этапов и согласование сроков в этой версии не включены.</p></div>`;
}
function bindProjects(){
 document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();openRecord('project',Number(b.dataset.project));}));
 document.querySelectorAll('[data-project-filter]').forEach(b=>b.addEventListener('click',()=>{projectFilter=b.dataset.projectFilter;render();}));
 document.querySelectorAll('[data-project-view]').forEach(b=>b.addEventListener('click',()=>{projectView=b.dataset.projectView;render();}));
}
